import React, { useState, useEffect, useContext } from 'react';
import EventForm from './EventForm';
import axios from 'axios';
import { useNavigate } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const Dashboard = () => {
  const [events, setEvents] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const { user, logout } = useContext(AuthContext) || {};
  const navigate = useNavigate();

  const currentUserId = user?.id || user?._id;

  const fetchEvents = async () => {
    if (!currentUserId) return;
    try {
      const res = await axios.get(`http://localhost:5000/api/events?userId=${currentUserId}`);
      setEvents(res.data);
    } catch (err) {
      console.error("Fetch error", err);
    }
  };

  useEffect(() => {
    fetchEvents();
  }, [currentUserId]);

  const styles = {
    container: {
      minHeight: '100vh',
      background: 'linear-gradient(135deg, #f5f7fa 0%, #c3cfe2 100%)',
      padding: '40px 20px',
      fontFamily: '"Segoe UI", Roboto, Helvetica, Arial, sans-serif'
    },
    wrapper: { maxWidth: '1000px', margin: '0 auto' },
    header: {
      display: 'flex',
      justifyContent: 'space-between',
      alignItems: 'center',
      marginBottom: '40px',
      backgroundColor: 'white',
      padding: '20px 30px',
      borderRadius: '16px',
      boxShadow: '0 4px 15px rgba(0,0,0,0.05)'
    },
    welcomeText: { fontSize: '24px', fontWeight: 'bold', color: '#2d3436', margin: 0 },
    logoutBtn: {
      padding: '10px 20px',
      backgroundColor: '#ff7675',
      color: 'white',
      border: 'none',
      borderRadius: '8px',
      cursor: 'pointer',
      fontWeight: '600',
      transition: '0.3s'
    },
    actionSection: { textAlign: 'right', marginBottom: '30px' },
    addBtn: {
      padding: '12px 24px',
      backgroundColor: showForm ? '#636e72' : '#6c5ce7',
      color: 'white',
      border: 'none',
      borderRadius: '12px',
      cursor: 'pointer',
      fontSize: '16px',
      fontWeight: '600',
      boxShadow: '0 4px 12px rgba(108, 92, 231, 0.3)'
    },
    formWrapper: {
      backgroundColor: 'white',
      padding: '30px',
      borderRadius: '20px',
      marginBottom: '40px',
      boxShadow: '0 10px 25px rgba(0,0,0,0.1)'
    },
    grid: { display: 'grid', gridTemplateColumns: 'repeat(auto-fill, minmax(300px, 1fr))', gap: '25px' },
    eventCard: {
      backgroundColor: 'white',
      padding: '25px',
      borderRadius: '16px',
      position: 'relative',
      transition: 'transform 0.2s, boxShadow 0.2s',
      boxShadow: '0 4px 6px rgba(0,0,0,0.02)',
      border: '1px solid #edf2f7'
    },
    badge: (isOrganizer) => ({
      fontSize: '10px',
      textTransform: 'uppercase',
      letterSpacing: '1px',
      padding: '4px 10px',
      borderRadius: '20px',
      backgroundColor: isOrganizer ? '#e0e7ff' : '#fef3c7',
      color: isOrganizer ? '#4338ca' : '#92400e',
      fontWeight: 'bold',
      display: 'inline-block',
      marginBottom: '15px'
    }),
    eventTitle: { fontSize: '20px', color: '#2d3436', margin: '0 0 10px 0', fontWeight: '700' },
    detailLine: { display: 'flex', alignItems: 'center', color: '#636e72', fontSize: '14px', margin: '8px 0' },
    emptyState: {
      textAlign: 'center',
      padding: '60px',
      backgroundColor: 'rgba(255,255,255,0.5)',
      borderRadius: '20px',
      border: '2px dashed #a29bfe'
    }
  };

  return (
    <div style={styles.container}>
      <div style={styles.wrapper}>
        <div style={styles.header}>
          <h1 style={styles.welcomeText}>👋 Hi, {user?.name}</h1>
          <button onClick={() => { logout(); navigate('/'); }} style={styles.logoutBtn}>Logout</button>
        </div>

        <div style={styles.actionSection}>
          <button onClick={() => setShowForm(!showForm)} style={styles.addBtn}>
            {showForm ? "✕ Cancel" : "＋ Create New Event"}
          </button>
        </div>

        {showForm && (
          <div style={styles.formWrapper}>
            <EventForm user={user} onEventCreated={() => { fetchEvents(); setShowForm(false); }} />
          </div>
        )}

        <h2 style={{ color: '#2d3436', marginBottom: '20px', fontSize: '22px' }}>Your Schedule</h2>

        {events.length === 0 ? (
          <div style={styles.emptyState}>
            <h3 style={{ color: '#6c5ce7', margin: 0 }}>Your calendar is clear!</h3>
            <p style={{ color: '#636e72' }}>Tap the button above to start your first event.</p>
          </div>
        ) : (
          <div style={styles.grid}>
            {events.map(e => {
              const isOrganizer = String(e.creator?._id || e.creator) === String(currentUserId);
              return (
                <div key={e._id} style={styles.eventCard} className="card-hover">
                  <span style={styles.badge(isOrganizer)}>
                    {isOrganizer ? "Organizer" : "Guest"}
                  </span>
                  <h4 style={styles.eventTitle}>{e.name}</h4>
                  <div style={styles.detailLine}>📅 {new Date(e.date).toLocaleDateString(undefined, { dateStyle: 'long' })}</div>
                  <div style={styles.detailLine}>📍 {e.location || "No location set"}</div>
                </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
};

export default Dashboard;
